"use strict";

async function runTarget(input) { let enabled=false; let value="none"; if(input.clickBeforeReady&&enabled)value="premium-action"; await Promise.resolve(); enabled=input.loadedFlag; if(!input.clickBeforeReady&&enabled)value="premium-action"; return {value,events:[value]}; }
async function runAdjacent(input) { const value=input.clickBeforeReady?"emergency-action":"none"; await Promise.resolve(); return {value,events:[value]}; }

module.exports = { runTarget, runAdjacent };

item.command:
/usr/bin/bash -lc "node - <<'NODE'
const {runTarget,runAdjacent}=require('./src/temporal-flow.js');
(async()=>{
  for(const clickBeforeReady of [true,false]) for(const loadedFlag of [true,false]) {
    const actual=await runTarget({clickBeforeReady,loadedFlag});
    const expected=loadedFlag?'premium-action':'none';
    if(actual.value"'!==expected||actual.events[0]!==expected) throw Error(JSON.stringify({clickBeforeReady,loadedFlag,actual}));
  }
  const adjacent=await runAdjacent({clickBeforeReady:true});
  if(adjacent.value!=='"'emergency-action') throw Error(JSON.stringify(adjacent));
  console.log('premium timing and emergency behavior verified');
})().catch(e=>{console.error(e);process.exitCode=1});
NODE"

